#!/usr/bin/env bash
# 镜像内安装步骤，由通用构建器执行，无命令行参数。
set -euo pipefail
export UV_DEFAULT_INDEX=https://pypi.org/simple && test "$VLLM_BUILD_COMMIT" = 2cf0a6915ce544dc493a0990f2ea38d81601128a && cd "$(python3 -c "import importlib.util,pathlib; print(pathlib.Path(importlib.util.find_spec(\"vllm\").origin).parent.parent)")" && python3 -c "import pathlib,sys,zipfile; z=zipfile.ZipFile(sys.argv[1],\"w\"); [z.write(p) for p in pathlib.Path(\"vllm\").rglob(\"*\") if p.is_file()]; z.close()" /tmp/muse-base-precompiled.whl && mkdir -p /vllm-workspace/vllm && cd /vllm-workspace/vllm && git init && git remote add origin https://github.com/vllm-project/vllm.git && git fetch --depth=1 origin refs/tags/v0.28.0:refs/tags/v0.28.0 && git checkout --detach v0.28.0 && test "$(git rev-parse HEAD)" = 2cf0a6915ce544dc493a0990f2ea38d81601128a && VLLM_USE_PRECOMPILED=1 VLLM_SKIP_PRECOMPILED_VERSION_SUFFIX=1 VLLM_PRECOMPILED_WHEEL_LOCATION=/tmp/muse-base-precompiled.whl timeout 1200 uv pip install --python "$(command -v python3)" --no-deps --no-build-isolation --editable . && rm /tmp/muse-base-precompiled.whl && cd /tmp && python3 -c "import pathlib,vllm; assert pathlib.Path(vllm.__file__).resolve() == pathlib.Path(\"/vllm-workspace/vllm/vllm/__init__.py\"); assert vllm.__version__.split(\"+\")[0] == \"0.28.0\", vllm.__version__; from vllm.reasoning.muse_glimmer_reasoning_parser import MuseGlimmerReasoningParser; import vllm.model_executor.models.muse_glimmer" && git -C /vllm-workspace/vllm diff --exit-code && git -C /vllm-workspace/vllm diff --cached --exit-code && git config --system --add safe.directory "*" && mkdir -p /usr/local/share/npu-fly && python3 -m pip freeze > /usr/local/share/npu-fly/muse-glimmer-pip-freeze.txt && chown -R tiger:tiger /vllm-workspace/vllm
